  with check (((coach_id = (select auth.uid())) AND private.is_group_staff(group_id) AND private.can_read_player_table(private.micro_answer_player(answer_id), 'Mistake'::text) AND (EXISTS ( SELECT 1 FROM group_members m WHERE ((m.group_id = micro_review_verdicts.group_id) AND (m.user_id = private.micro_answer_player(micro_review_verdicts.answer_id)))))));
